function AddModal({state,aiConnected,onClose,onAdd}:{state:LearningState;aiConnected:boolean;onClose:()=>void;onAdd:(r:Resource)=>void}){
 const [tab,setTab]=useState('link');const [title,setTitle]=useState('');const [url,setUrl]=useState('');const [provider,setProvider]=useState('');const [kind,setKind]=useState<Resource['kind']>('course');const [goalId,setGoalId]=useState(state.settings.focusGoal);const [priority,setPriority]=useState(3);const [minutes,setMinutes]=useState(15);const [syllabus,setSyllabus]=useState('');const [preview,setPreview]=useState<Partial<Lesson>[]|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [deadline,setDeadline]=useState('');const [folderPath,setFolderPath]=useState('');const [scope,setScope]=useState<Resource['captureScope']>('manual');const [captureNote,setCaptureNote]=useState('');const [mergeId,setMergeId]=useState('');const [bookMeta,setBookMeta]=useState({bookPages:0,bookFileName:'',outlineSource:'manual' as Resource['outlineSource']});const [groupRequest,setGroupRequest]=useState('Group these lessons by topic. Keep DevOps, Docker, deployment and CI/CD together.');
 const valid=title.trim()&&(!url||!!safeUrl(url));
 async function inspectLink(){setBusy(true);setError('');setNotice('');try{const r=await apiRequest('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const d=await r.json() as Payload;if(!r.ok)throw Error(d.error);if(d.title)setTitle(d.title);setProvider(d.provider);if(d.notice)setNotice(d.notice);if(url.includes('youtu'))setKind(url.includes('list=')?'course':'video');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function fileImport(file:File){setError('');try{if(file.size>4000000)throw Error('File exceeds 4 MB.');const data=JSON.parse(await file.text());if(data.version===1&&data.resources)throw Error('This is a full backup. Use Settings → Restore a backup.');const raw=data.resource||data;if(!raw.title||!Array.isArray(raw.lessons)||!raw.lessons.length)throw Error('Use a JSON object with a title and a non-empty lessons array.');const candidate=makeResource({title:raw.title,provider:raw.provider||'Imported',kind:raw.kind||'course',url:raw.url||'',priority:raw.priority||3,bookPages:raw.bookPages||0,bookFileName:raw.bookFileName||'',outlineSource:raw.outlineSource||'manual',folderPath:normalizePath(raw.folderPath||''),captureScope:raw.captureScope||'manual',captureNote:raw.captureNote||''},raw.lessons.map((l:Partial<Lesson>)=>({...l,id:uid(),completedAt:null,pinned:false,studiedMinutes:0})));setTitle(candidate.title);setUrl(candidate.url);setProvider(candidate.provider);setKind(candidate.kind);setPriority(candidate.priority);setFolderPath(candidate.folderPath);setScope(candidate.captureScope);setCaptureNote(candidate.captureNote);setBookMeta({bookPages:candidate.bookPages,bookFileName:candidate.bookFileName,outlineSource:candidate.outlineSource});setPreview(candidate.lessons);setNotice('Loaded '+candidate.lessons.length+' items. Review folders, durations, and source links. Imported progress won’t create study history.');}catch(e){setError((e as Error).message);}}
 function suggestTopics(){if(!preview)return;setPreview(p=>p!.map(l=>({...l,modulePath:suggestModule(l.title||'')})));setNotice('Topic suggestions added to the preview using title matching. Edit anything that doesn’t fit. Source order and links are unchanged.');}
 async function organizeAI(){if(!preview)return;setBusy(true);setError('');try{const lessons=preview.map((l,i)=>({id:l.id||String(i),title:l.title,modulePath:l.modulePath||''}));const r=await apiRequest('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'group',prompt:groupRequest,courseTitle:title,lessons})});const d=await r.json() as {error?:string;message:string;assignments:{lessonId:string;modulePath:string}[]};if(!r.ok)throw Error(d.error);setPreview(p=>p!.map((l,i)=>({...l,modulePath:d.assignments.find(a=>a.lessonId===(l.id||String(i)))?.modulePath||l.modulePath||''})));setNotice(d.message+' Review the suggested folders before importing.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 function submit(){setError('');try{if(!valid)throw Error('Add a title and check the source link.');const lessons=preview||(tab==='syllabus'&&syllabus.trim()?parseSyllabus(syllabus,minutes):[{title:title.trim(),minutes,url}]);const incoming=makeResource({title:title.trim(),url,provider:provider||'Personal',kind,goalId,priority,deadline,folderPath:normalizePath(folderPath),captureScope:scope,captureNote,...bookMeta,color:kind==='article'?'orange':kind==='video'?'lavender':kind==='topic'?'blue':'teal'},lessons.map(l=>({...l,id:l.id||uid(),modulePath:normalizePath(l.modulePath||''),url:l.url||''})));const existing=state.resources.find(r=>r.id===mergeId);const final=existing?resourceSchema.parse(mergeCourse(existing,incoming)):incoming;if(!existing&&state.resources.some(x=>!x.demo&&url&&x.url===url)&&!confirm('This source is already in your library. Add another course, or cancel and choose Merge into an existing course.'))return;onAdd(final);}catch(e){setError((e as Error).message);}}
 const changeTab=(id:string)=>{setTab(id);setError('');};
 return <ModalFrame title="Bring your learning together" subtitle="Capture an outline, keep its folders, and choose what matters." onClose={onClose} wide><div className="import-tabs">{[{id:'link',label:'Link',icon:Link2},{id:'syllabus',label:'Syllabus',icon:FileText},{id:'file',label:'File',icon:Upload},{id:'capture',label:'Browser capture',icon:Compass}].map(t=><button className={tab===t.id?'selected':''} key={t.id} onClick={()=>changeTab(t.id)}><t.icon size={16}/>{t.label}</button>)}</div><div className="modal-content">
 {tab==='capture'&&<div className="capture-guide"><span className="lesson-symbol teal"><Compass size={23}/></span><h3>Your course stays on its platform.<br/>Its learning plan lives here.</h3><p>Use the Chrome companion on a course outline or folder. It captures loaded titles, durations, groups, and exposed links into an editable draft.</p><ol><li>Load the companion in Chrome and open your course.</li><li>Expand the folder, capture it, and review the draft.</li><li>Use Scan chapters for collapsed outlines, then merge additional folders when needed.</li><li>Download the course JSON and import it here.</li></ol><div className="capture-guide-actions"><a className="primary" href="/downloads/learning-space-companion.zip" download><Download size={15}/> Download Chrome companion</a><button className="secondary" onClick={()=>setTab('file')}>Import a capture <ArrowRight size={15}/></button></div><p className="capture-limit">Prototype · Reads loaded outline metadata on your click. Collapsed or unloaded folders need further captures. Scan chapters expands recognized outline disclosures. Some sites expose folder links rather than individual video links.</p></div>}
 {tab==='link'&&<label>Source link<div className="input-with-button"><input placeholder="https://www.boot.dev/lessons/..." value={url} onChange={e=>setUrl(e.target.value)} type="url"/><button className="secondary" onClick={inspectLink} disabled={busy||!safeUrl(url)}>{busy?<Loader2 className="spin" size={15}/>:<Sparkles size={15}/>}Get details</button></div><small>One link saves a resource. For a complete loaded outline from Boot.dev or 100xDevs, use Browser capture or paste a syllabus.</small></label>}
 {tab==='syllabus'&&<><label>Lesson list<textarea value={syllabus} onChange={e=>{setSyllabus(e.target.value);setPreview(null);}} rows={6} placeholder={'Use > to preserve folders:\nDevOps > Docker > Images | 15 min | https://...\nDevOps > Docker > Containers | 25 min | https://... | done\nWeb > React > State | 20 min'}/><small>Folder &gt; module &gt; title | minutes | optional link | optional “done”. Folders stay editable.</small></label><button className="secondary" disabled={!syllabus.trim()} onClick={()=>{setPreview(parseSyllabus(syllabus,minutes).map(l=>({...l,id:uid()})));setNotice('Syllabus parsed. Review titles, modules, and durations.');}}>Preview lessons</button></>}
 {tab==='file'&&<label className="upload-zone"><Upload size={26}/><strong>Choose a course or capture JSON file</strong><span>Up to 4 MB · Groups and source links stay with the lessons</span><input type="file" accept=".json,application/json" onChange={e=>{if(e.target.files?.[0])fileImport(e.target.files[0]);}}/></label>}
 {tab!=='capture'&&<><div className="form-grid"><label className="span-two">Course / resource title<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="100xDevs · Web development & DevOps" maxLength={250}/></label><label>Resource type<select value={kind} onChange={e=>setKind(e.target.value as Resource['kind'])}>{Object.entries(kindLabel).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label>Provider / creator<input value={provider} onChange={e=>setProvider(e.target.value)} placeholder="Boot.dev, 100xDevs, YouTube…" maxLength={100}/></label><label className="span-two">Learning area / folder<input value={folderPath} onChange={e=>setFolderPath(e.target.value)} placeholder="DevOps / Containers" maxLength={200} list="learning-folders"/><datalist id="learning-folders">{Array.from(new Set(state.resources.map(r=>r.folderPath).filter(Boolean))).map(f=><option key={f}>{f}</option>)}</datalist><small>This organizes the course in your library. Each lesson can have its own module below.</small></label>{tab!=='link'&&<label className="span-two">Source link (optional)<input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://..." type="url"/></label>}<label>Learning goal<select value={goalId} onChange={e=>setGoalId(e.target.value)}><option value="">Just curious</option>{state.goals.map(g=><option key={g.id} value={g.id}>{g.title}</option>)}</select></label><label>Priority<select value={priority} onChange={e=>setPriority(Number(e.target.value))}>{priorityLabels.slice(1).map((p,i)=><option value={i+1} key={p}>{i+1} · {p}</option>)}</select></label><label>Default duration (minutes)<input type="number" min={1} max={600} value={minutes} onChange={e=>setMinutes(Number(e.target.value))}/></label><label>Deadline (optional)<input type="date" value={deadline} onChange={e=>setDeadline(e.target.value)}/></label><label className="span-two">Add or merge<select value={mergeId} onChange={e=>setMergeId(e.target.value)}><option value="">Add as a new course / resource</option>{state.resources.filter(r=>r.kind==='course'&&!r.archived).map(r=><option key={r.id} value={r.id}>Merge into {r.title}</option>)}</select><small>Merging adds new items and keeps existing notes, IDs, completion, and module choices.</small></label></div>
 {captureNote&&<div className="capture-scope"><strong>{scope==='manual'?'Imported outline':'Captured page outline'}</strong><p>{captureNote}</p></div>}{notice&&<div className="import-notice"><CircleHelp size={16}/>{notice}</div>}
 {preview&&<div className="import-preview"><div className="preview-heading"><h3>Review {preview.length} items <span>{preview.reduce((n,l)=>n+(l.minutes||15),0)} min</span></h3><button className="text-button" onClick={suggestTopics}><Layers size={14}/> Suggest topic folders</button></div><details className="ai-grouping"><summary><Sparkles size={14}/> Organize with your AI coach {aiConnected?'':'· connection needed'}</summary><label>How should these lessons be organized?<textarea rows={2} value={groupRequest} onChange={e=>setGroupRequest(e.target.value)} maxLength={12000}/></label><button className="secondary" disabled={busy||!aiConnected||!groupRequest.trim()} onClick={organizeAI}><Sparkles size={14}/>{busy?'Suggesting groups…':'Suggest modules with AI'}</button><small>Uses course title and lesson metadata. Suggestions change this preview; import only after you’ve reviewed them.</small></details><div className="capture-preview-list">{preview.map((l,i)=><div className="grouped-preview-row" key={l.id||i}><span>{i+1}</span><div><input aria-label={'Lesson '+(i+1)+' title'} value={l.title||''} onChange={e=>setPreview(p=>p!.map((x,j)=>j===i?{...x,title:e.target.value}:x))}/><div className="preview-fields"><input aria-label={'Lesson '+(i+1)+' module'} placeholder="Module / subfolder" value={l.modulePath||''} maxLength={200} onChange={e=>setPreview(p=>p!.map((x,j)=>j===i?{...x,modulePath:e.target.value}:x))}/><select aria-label={'Lesson '+(i+1)+' format'} value={l.format||'video'} onChange={e=>setPreview(p=>p!.map((x,j)=>j===i?{...x,format:e.target.value as Lesson['format']}:x))}><option value="video">Video</option><option value="exercise">Exercise</option><option value="reading">Reading</option></select></div><input aria-label={'Lesson '+(i+1)+' source link'} placeholder="Direct lesson URL (optional)" type="url" value={l.url||''} onChange={e=>setPreview(p=>p!.map((x,j)=>j===i?{...x,url:e.target.value}:x))}/></div><div className="preview-options"><input aria-label={'Lesson '+(i+1)+' minutes'} type="number" min={1} max={600} value={l.minutes||15} onChange={e=>setPreview(p=>p!.map((x,j)=>j===i?{...x,minutes:Number(e.target.value)}:x))}/><label className="preview-done"><input type="checkbox" checked={!!l.done} onChange={e=>setPreview(p=>p!.map((x,j)=>j===i?{...x,done:e.target.checked}:x))}/>Done</label><button className="icon-button" aria-label={'Remove lesson '+(i+1)} onClick={()=>setPreview(p=>p!.filter((_,j)=>j!==i))}><X size={13}/></button></div></div>)}</div></div>}{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={!valid||busy||(tab==='file'&&!preview?.length)||(preview!==null&&!preview.length)} onClick={submit}><Plus size={16}/>{mergeId?'Merge into my course':'Add to my library'}</button></div></>}
 </div></ModalFrame>;
}
function GoalModal({goal,onSave,onDelete,onClose}:{goal?:LearningState['goals'][number];onSave:(g:LearningState['goals'][number])=>void;onDelete:(id:string)=>void;onClose:()=>void}){
 const [title,setTitle]=useState(goal?.title||'');const [description,setDescription]=useState(goal?.description||'');const [importance,setImportance]=useState(goal?.importance||4);
 return <ModalFrame title={goal?'Shape your learning goal':'Give your learning a direction'} subtitle="A goal can be a skill, a project, or a person you want to become." onClose={onClose}><div className="modal-content"><label>What do you want to achieve?<input value={title} onChange={e=>setTitle(e.target.value)} maxLength={120} placeholder="Build and launch my first AI app"/></label><label>Why does this matter to you?<textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)} maxLength={500} placeholder="A little context for your future self…"/></label><label>Importance<select value={importance} onChange={e=>setImportance(Number(e.target.value))}>{priorityLabels.slice(1).map((p,i)=><option key={p} value={i+1}>{i+1} · {p}</option>)}</select></label><div className="modal-actions">{goal&&<button className="danger-button" onClick={()=>{if(confirm('Delete this goal? Its resources will stay in your library.'))onDelete(goal.id);}}><Trash2 size={15}/> Delete goal</button>}<button className="primary" disabled={!title.trim()} onClick={()=>onSave({id:goal?.id||uid(),title:title.trim(),description,importance})}>Save goal <Check size={16}/></button></div></div></ModalFrame>;
}
function ResourceModal({r,state,onClose,patch,lessonPatch,toggle,start,onDelete,aiConnected}:{r:Resource;state:LearningState;onClose:()=>void;patch:(p:Partial<Resource>)=>void;lessonPatch:(id:string,p:Partial<Lesson>)=>void;toggle:(id:string)=>void;start:(id:string)=>void;onDelete:()=>void;aiConnected:boolean}){
 const [tab,setTab]=useState('lessons');const [editTitle,setEditTitle]=useState(r.title);const [editUrl,setEditUrl]=useState(r.url);const [newLesson,setNewLesson]=useState('');const [newDuration,setNewDuration]=useState(15);const [newModule,setNewModule]=useState(r.focusModule);const [selectedNote,setSelectedNote]=useState('');const [editingLesson,setEditingLesson]=useState('');const [groupSuggestions,setGroupSuggestions]=useState<{lessonId:string;modulePath:string}[]|null>(null);const [groupMessage,setGroupMessage]=useState('');const [groupBusy,setGroupBusy]=useState(false);const [groupError,setGroupError]=useState('');
 const next=eligibleLessons(r)[0];const groups=groupLessons(r.lessons);
 async function aiGroups(){setGroupBusy(true);setGroupError('');try{const response=await apiRequest('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'group',prompt:'Suggest useful topic-based module folders for this course. Use DevOps, Backend, Web, or other appropriate learning areas, with subfolders when helpful.',courseTitle:r.title,lessons:r.lessons.map(l=>({id:l.id,title:l.title,modulePath:l.modulePath}))})});const d=await response.json() as {error?:string;message:string;assignments:{lessonId:string;modulePath:string}[]};if(!response.ok)throw Error(d.error);setGroupSuggestions(d.assignments);setGroupMessage(d.message);}catch(e){setGroupError((e as Error).message);}finally{setGroupBusy(false);}}
 return <ModalFrame title={r.title} subtitle={[r.folderPath,r.provider,kindLabel[r.kind],r.demo?'Sample content':''].filter(Boolean).join(' · ')} onClose={onClose} wide><div className="resource-overview"><Art type={r.color}/><div><div className="overview-tags"><span className="priority-tag">{priorityLabels[r.priority]}</span>{r.archived&&<span className="priority-tag">Archived</span>}<span>{r.lessons.filter(l=>l.done).length} / {r.lessons.length} completed</span></div><div className="progress-track"><i style={{width:progress(r)+'%'}}/></div><p>{r.focusModule?'Learning focus: '+r.focusModule:rankReason(r,state)}</p>{r.kind==='book'&&<small>{r.bookPages?r.bookPages+' pages · ':''}{r.outlineSource==='ai-plan'?'Suggested reading plan':r.outlineSource.replaceAll('-',' ')} · original file stays on the importing device</small>}<div className="resource-actions">{r.kind==='book'&&<label className="file-button secondary small"><Upload size={14}/>Attach original on this device<input type="file" accept=".pdf,.epub,application/pdf,application/epub+zip" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>50*1024*1024||!/\.(pdf|epub)$/i.test(file.name))throw Error('Choose a PDF or EPUB under 50 MB.');await cacheBook(r.id,file);patch({bookFileName:file.name});}catch(err){alert((err as Error).message);}e.target.value='';}}/></label>}{r.kind==='book'&&r.bookFileName&&<button className="secondary small" onClick={async()=>{if(!await openBook(r.id))alert('The original file is stored only on the device where it was imported. Attach the matching original file on this device, or open it in your PDF reader.');}}><BookOpen size={14}/>Open book file</button>}{next&&<button className="primary small" onClick={()=>start(next.id)}><Play size={13} fill="currentColor"/> Continue learning</button>}{r.url&&<a className="secondary small" href={r.url} target="_blank" rel="noreferrer">Open source <ArrowUpRight size={14}/></a>}</div>{r.demo&&<small>Illustrative lessons. Replace these with your own course syllabus.</small>}</div></div><div className="import-tabs">{['lessons','notes','details'].map(t=><button className={tab===t?'selected':''} key={t} onClick={()=>setTab(t)}>{t==='lessons'?<Layers size={15}/>:t==='notes'?<StickyNote size={15}/>:<Settings size={15}/>} {t==='lessons'?'Modules & lessons':t[0].toUpperCase()+t.slice(1)}</button>)}</div><div className="modal-content">
 {tab==='lessons'&&<><div className="module-focus"><label>What part of this course matters right now?<select aria-label="Focus on a course module" value={r.focusModule} onChange={e=>patch({focusModule:e.target.value})}><option value="">Entire course, in source order</option>{Array.from(new Set(r.lessons.flatMap(l=>l.modulePath.split('/').map((_,i,a)=>a.slice(0,i+1).join('/'))).filter(Boolean))).map(m=><option key={m} value={m}>{m.replaceAll('/',' / ')}</option>)}</select><small>Today’s queue uses only this module and its subfolders. Progress and notes for the rest of the course stay here.</small></label><div className="module-tools"><button className="text-button" onClick={()=>{setGroupSuggestions(r.lessons.map(l=>({lessonId:l.id,modulePath:suggestModule(l.title)})));setGroupMessage('Topic suggestions from title matching. Source order stays unchanged.');}}><Layers size={14}/> Suggest topic folders</button><button className="text-button" disabled={!aiConnected||groupBusy} onClick={aiGroups} title={aiConnected?'Ask the AI coach to suggest grouping':'Connect the server-side OpenAI key to enable AI grouping'}><Sparkles size={14}/>{groupBusy?'Thinking…':'Ask AI to group'}</button></div></div>
 {groupError&&<p className="form-error" role="alert">{groupError}</p>}{groupSuggestions&&<div className="group-suggestions"><h3>Review suggested folders</h3><p>{groupMessage}</p><div>{groupSuggestions.map(a=><label key={a.lessonId}><span>{r.lessons.find(l=>l.id===a.lessonId)?.title}</span><input aria-label={'Suggested module for '+a.lessonId} value={a.modulePath} maxLength={200} onChange={e=>setGroupSuggestions(p=>p!.map(x=>x.lessonId===a.lessonId?{...x,modulePath:e.target.value}:x))}/></label>)}</div><div className="module-tools"><button className="primary small" onClick={()=>{patch({lessons:r.lessons.map(l=>({...l,modulePath:normalizePath(groupSuggestions.find(a=>a.lessonId===l.id)?.modulePath||l.modulePath)})),focusModule:''});setGroupSuggestions(null);}}><Check size={14}/> Apply these folders</button><button className="secondary small" onClick={()=>setGroupSuggestions(null)}>Discard</button></div></div>}
 <div className="module-list">{groups.filter(group=>!r.focusModule||group.path===r.focusModule||group.path.startsWith(r.focusModule+'/')).map(group=><details open key={group.path} className={'module-group '+(r.focusModule&&(group.path===r.focusModule||group.path.startsWith(r.focusModule+'/'))?'module-active':'')}><summary><span><Layers size={15}/>{group.path.replaceAll('/',' / ')}</span><small>{group.lessons.filter(l=>l.done).length}/{group.lessons.length} done · {group.lessons.reduce((n,l)=>n+l.minutes-l.studiedMinutes,0)} min remaining</small></summary>{group.lessons.map(l=><div key={l.id}><div className={'syllabus-row '+(l.done?'done':'')}><button className="lesson-check" aria-label={(l.done?'Mark unfinished: ':'Mark complete: ')+l.title} onClick={()=>toggle(l.id)}>{l.done?<Check size={14}/>:<span/>}</button><span className="lesson-index">{r.lessons.indexOf(l)+1}</span><button className="syllabus-lesson" onClick={()=>start(l.id)}><strong>{l.title}</strong><span>{l.format} · {l.minutes} min{l.pageStart?' · p. '+l.pageStart+(l.pageEnd?'–'+l.pageEnd:''):''}{l.studiedMinutes>0?' · '+l.studiedMinutes+' min studied':''} {l.notes&&'· Has notes'}</span></button><button className="icon-button" aria-label={'Edit lesson '+l.title} onClick={()=>setEditingLesson(editingLesson===l.id?'':l.id)}><Settings size={14}/></button><button className={'icon-button '+(l.pinned?'pinned':'')} onClick={()=>lessonPatch(l.id,{pinned:!l.pinned})} aria-label={l.pinned?'Unpin '+l.title:'Pin '+l.title}><Pin size={14}/></button></div>{editingLesson===l.id&&<div className="inline-lesson-editor"><label>Module / folder<input value={l.modulePath} onChange={e=>lessonPatch(l.id,{modulePath:e.target.value})} onBlur={()=>lessonPatch(l.id,{modulePath:normalizePath(l.modulePath)})} maxLength={200} placeholder="DevOps / Docker"/></label><label>Lesson source URL<input defaultValue={l.url} onBlur={e=>{if(!e.target.value||safeUrl(e.target.value))lessonPatch(l.id,{url:e.target.value});}} placeholder="https://..." type="url"/></label><label>Format<select value={l.format} onChange={e=>lessonPatch(l.id,{format:e.target.value as Lesson['format']})}><option value="video">Video</option><option value="exercise">Exercise</option><option value="reading">Reading</option></select></label><small>Duration: {l.minutes} minutes. Direct links are optional; the source course opens when none is available.</small></div>}</div>)}</details>)}</div><div className="add-lesson-fields"><label>New lesson<input value={newLesson} onChange={e=>setNewLesson(e.target.value)} placeholder="Add another lesson…" maxLength={250}/></label><label>Module<input value={newModule} onChange={e=>setNewModule(e.target.value)} placeholder="DevOps / Docker" maxLength={200}/></label><label>Minutes<input type="number" min={1} max={600} value={newDuration} onChange={e=>setNewDuration(Number(e.target.value))}/></label><button className="secondary" disabled={!newLesson.trim()||newDuration<1||newDuration>600||!Number.isInteger(newDuration)||r.lessons.length>=500} onClick={()=>{patch({lessons:[...r.lessons,lessonSchema.parse({id:uid(),title:newLesson.trim(),minutes:newDuration,url:'',done:false,completedAt:null,notes:'',pinned:false,modulePath:normalizePath(newModule)})]});setNewLesson('');}}><Plus size={16}/>Add</button></div>{r.captureNote&&<div className="capture-scope"><strong>Import coverage</strong><p>{r.captureNote}</p></div>}</>}
 {tab==='notes'&&<><label>Resource notes<textarea rows={4} value={r.notes} onChange={e=>patch({notes:e.target.value})} maxLength={10000} placeholder="Your takeaways, ideas, and questions…"/></label><label>Notes for a lesson<select value={selectedNote} onChange={e=>setSelectedNote(e.target.value)}><option value="">Choose a lesson</option>{r.lessons.map(l=><option key={l.id} value={l.id}>{l.modulePath?l.modulePath+' / ':''}{l.title}</option>)}</select></label>{selectedNote&&<label>Lesson notes<textarea rows={5} value={r.lessons.find(l=>l.id===selectedNote)?.notes||''} onChange={e=>lessonPatch(selectedNote,{notes:e.target.value})} maxLength={10000} placeholder="What clicked? What do you want to try?"/></label>}<small>Notes save automatically and appear in My notes.</small></>}
 {tab==='details'&&<><div className="form-grid"><label className="span-two">Title<input value={editTitle} onChange={e=>setEditTitle(e.target.value)} maxLength={250} onBlur={()=>{if(editTitle.trim())patch({title:editTitle.trim()});}}/></label><label className="span-two">Learning area / folder<input value={r.folderPath} onChange={e=>patch({folderPath:e.target.value})} onBlur={()=>patch({folderPath:normalizePath(r.folderPath)})} maxLength={200} placeholder="DevOps / Containers"/></label><label className="span-two">Source link<input type="url" value={editUrl} onChange={e=>setEditUrl(e.target.value)} onBlur={()=>{if(!editUrl||safeUrl(editUrl))patch({url:editUrl});}}/>{editUrl&&!safeUrl(editUrl)&&<small className="form-error">Use a valid http or https link.</small>}</label><label>Priority<select value={r.priority} onChange={e=>patch({priority:Number(e.target.value)})}>{priorityLabels.slice(1).map((p,i)=><option key={p} value={i+1}>{i+1} · {p}</option>)}</select></label><label>Learning goal<select value={r.goalId} onChange={e=>patch({goalId:e.target.value})}><option value="">Just curious</option>{state.goals.map(g=><option value={g.id} key={g.id}>{g.title}</option>)}</select></label><label>Deadline<input type="date" value={r.deadline} onChange={e=>patch({deadline:e.target.value})}/></label><label>Resource type<select value={r.kind} onChange={e=>patch({kind:e.target.value as Resource['kind']})}>{Object.entries(kindLabel).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label></div><div className="resource-management"><button className="secondary" onClick={()=>patch({archived:!r.archived})}>{r.archived?<RotateCcw size={15}/>:<Archive size={15}/>} {r.archived?'Return to library':'Archive resource'}</button><button className="danger-button" onClick={()=>{if(confirm('Permanently delete this resource and its lesson notes?'))onDelete();}}><Trash2 size={15}/> Delete resource</button></div></>}
 </div></ModalFrame>;
}
function SessionModal({resource,lesson,onClose,onNote,onComplete,plannedMinutes,onBlock}:{resource:Resource;lesson:Lesson;onClose:()=>void;onNote:(s:string)=>void;onComplete:()=>void;plannedMinutes:number;onBlock:(minutes:number)=>void}){
 const [elapsed,setElapsed]=useState(0);const [running,setRunning]=useState(false);const [block,setBlock]=useState(Math.max(1,plannedMinutes));const started=useRef(0);const accumulated=useRef(0);const remaining=Math.max(0,lesson.minutes-lesson.studiedMinutes);
 useEffect(()=>{if(!running)return;started.current=Date.now();const t=setInterval(()=>setElapsed(accumulated.current+Math.floor((Date.now()-started.current)/1000)),500);return()=>{accumulated.current+=Math.floor((Date.now()-started.current)/1000);clearInterval(t);};},[running]);
 return <ModalFrame title="A little time, just for learning" subtitle={resource.title+(lesson.modulePath?' · '+lesson.modulePath:'')} onClose={onClose}><div className="session-content"><span className={'lesson-symbol '+resource.color}><IconKind kind={resource.kind} size={24}/></span><h2>{lesson.title}</h2><p>{lesson.format} · {lesson.minutes} min total{lesson.pageStart?' · p. '+lesson.pageStart+(lesson.pageEnd?'–'+lesson.pageEnd:''):''}{resource.demo?' · Sample lesson':''}</p>{lesson.studiedMinutes>0&&<div className="study-position"><CheckCircle2 size={16}/>{lesson.studiedMinutes} minutes studied · {remaining} min remaining<small>Your logged study position is an estimate. Resume at about {lesson.studiedMinutes}:00 in the source player.</small></div>}<div className="session-timer"><strong>{String(Math.floor(elapsed/60)).padStart(2,'0')}<span>:</span>{String(elapsed%60).padStart(2,'0')}</strong><button className="secondary" onClick={()=>setRunning(v=>!v)}>{running?<Pause size={15}/>:<Play size={15}/>} {running?'Pause timer':'Start timer'}</button></div>{resource.kind==='book'&&resource.bookFileName&&<button className="secondary full" onClick={async()=>{if(!await openBook(resource.id))alert('Open the original PDF or EPUB in your reading app. Files are local to the device where they were imported.');}}><BookOpen size={15}/>Open original book on this device</button>}{(lesson.url||resource.url)?<a className="primary full" href={lesson.url||resource.url} target="_blank" rel="noreferrer">Open learning material <ArrowUpRight size={16}/></a>:<div className="import-notice"><CircleHelp size={16}/>Open your learning material in its original app, or add a source link in Details.</div>}<label>What did you learn?<textarea rows={3} value={lesson.notes} onChange={e=>onNote(e.target.value)} maxLength={10000} placeholder="One idea, a question, or something to try…"/></label>{!lesson.done&&<div className="study-block"><div><h3>Make progress without finishing it all</h3><p>Log a study block. The lesson stays in your queue until complete.</p></div><label>Minutes studied<input type="number" min={1} max={remaining} value={block} onChange={e=>setBlock(Number(e.target.value))}/></label><button className="secondary" disabled={!Number.isInteger(block)||block<1||block>remaining} onClick={()=>onBlock(block)}><Check size={15}/>Log this block</button></div>}<small>Logging a block records those minutes. Mark complete records the unlogged remaining duration. The timer is a focus aid and does not log time automatically.</small><div className="modal-actions"><button className="secondary" onClick={onClose}>Save for later</button><button className="primary" onClick={onComplete}><Check size={16}/>{lesson.done?'Already completed · Close':'Mark lesson complete'}</button></div></div></ModalFrame>;
}
